import{_ as e,o as n,c as a,a0 as t}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /api-integration","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/api-integration.md","filePath":"references/skills/api-integration.md"}'),o={name:"references/skills/api-integration.md"};function c(r,i,l,s,h,d){return n(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="skill-api-integration" tabindex="-1">Skill: <code>/api-integration</code> <a class="header-anchor" href="#skill-api-integration" aria-label="Permalink to &quot;Skill: `/api-integration`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>api-integration</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/api-integration &lt;provider/slug&gt;</code> (Ví dụ: <code>/api-integration stripe/charge</code>)</li><li>Dùng ĐỘC QUYỀN cho các API tích hợp ngoại vi (Partner APIs, Webhooks inbound/outbound) không có giao diện Portal FE đi kèm.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Tên Provider, danh sách các Event webhook, tài liệu PDF hoặc OpenAPI URL của đối tác (Partner).</li><li>Các file legacy controller cũ (nếu muốn reverse-engineer lại).</li><li>Các ghi chú lưu tại <code>docs/integrations/{provider}/*.md</code>.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Tạo ra thư mục tích hợp mới tại: <code>surfaces/integrations/&lt;provider&gt;/&lt;slug&gt;/api/&lt;seq&gt;/</code>.</li><li>Sinh ra bộ 3 file quen thuộc: <code>01-backend-spec.yaml</code>, <code>02-openapi.yaml</code> (dùng <code>flowgrid openapi_gen</code>), và <code>03-mock-data.yaml</code>.</li><li>Dữ liệu <code>portalRefs</code> sẽ rỗng (empty), thay vào đó khai báo các mảng <code>integrationRefs[]</code> và <code>integrationBacklog[]</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Khác với <code>/api-spec</code> chuyên phục vụ cho giao diện Frontend nội bộ, kỹ năng này dành riêng cho thế giới không giao diện (No Portal FE).</li><li>Đóng vai trò là cầu nối chuẩn hoá hợp đồng giao tiếp giữa hệ thống FlowGrid và các đối tác bên ngoài (Ví dụ: Cổng thanh toán Stripe, Push Notification Firebase, v.v.).</li><li>Yêu cầu bắt buộc tuân thủ quy tắc <strong>Tái sử dụng API (API Reuse)</strong> để không bị duplicate các webhooks, và quy tắc <strong>Đặt tên Action rõ ràng (Explicit URI Naming)</strong> (VD: <code>/api/v1/integrations/&lt;provider&gt;/webhook</code>).</li><li>Đòi hỏi phải định nghĩa rõ các mã lỗi từ đối tác (Integration Error Storming) như lỗi chữ ký số (<code>#err:signature-invalid</code>), lỗi giới hạn request (<code>#err:rate-limit</code>).</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Thay thế cho:</strong> <code>/api-spec</code> (Nếu màn hình đó có UI thì KHÔNG ĐƯỢC DÙNG lệnh này, mà phải dùng <code>/api-spec</code>).</li><li><strong>Sau đó:</strong> Bị review gắt gao bởi <code>/grill-integration-spec</code> (để gắn tag sinh code và kiểm định).</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Cấm đoán:</strong> Tuyệt đối không sinh Markdown report hay gộp chung nhiều provider/endpoint vào cùng 1 file. Không được gắn cờ sinh code (<code>codegen</code>, <code>#gen:*</code>) ở bước này.</li><li><strong>Luật AskQuestion Tech Debt:</strong> Các thông tin bảo mật như Chữ ký (Signature), Retention, Retry logic... nếu không rõ, Agent phải mở form AskQuestion hỏi Member. Bắt buộc có option <code>&quot;Log as Tech Debt&quot;</code>. Trả lời &quot;Tech Debt&quot; sẽ sinh file trong <code>qa/open/</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api-integration</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const p=e(o,[["render",c]]);export{u as __pageData,p as default};
